(()=>{'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const origin='https://kvolleylab.com/',url=p=>new URL(p,origin).href;
let db, gender=new URLSearchParams(location.search).get('gender')==='women'?'women':'men',position='전체';
// Reuse the operational navigation verbatim; only resolve destinations for the isolated host.
function route(root=document){root.querySelectorAll?.('a[href]').forEach(a=>{let h=a.getAttribute('href');if(!h||h[0]==='#'||/^(https?:|mailto:)/.test(h))return; if(h.split('?')[0]==='national-team.html')a.href='national-team.html?gender='+gender;else a.href=url(h);});}
new MutationObserver(()=>route()).observe(document.body,{childList:true,subtree:true});route();
const calendar='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v5m8-5v5M4 11h16m-11 5h6"/></svg>';
function matchCard(m,next=false){if(!m)return `<article class="match-card"><div class="match-top"><span class="match-label">${next?'다음 경기':'최근 경기'}</span><span class="badge neutral">${next?'발표 대기':'자료 미확인'}</span></div><div class="match-empty">${calendar}<strong>${next?'다음 일정 미정':'확인된 경기 없음'}</strong><p>${next?'등록된 다음 경기 일정이 없습니다.':'경기 결과 자료를 확인하고 있습니다.'}</p></div><a class="match-foot" href="${origin}competition.html?division=national"><span>대표팀 국제대회 일정 확인</span><span>↗</span></a></article>`;
const score=m.score,win=score&&score[0]>score[1];return `<a class="match-card" href="${url(m.href)}"><div class="match-top"><span class="match-label">${next?'다음 경기':'최근 경기 결과'}</span><span class="badge ${win?'':'neutral'}">${next?'예정':win?'승리':'패배'}</span></div><div class="match-context">${esc(m.competition)} · ${esc(m.stage)}</div><div class="match-score"><span class="nation">대한민국<small class="nation-code">KOR</small></span><b class="score">${score?score.join(' : '):'VS'}</b><span class="nation">${esc(m.opponent)}<small class="nation-code">${esc(m.opponentCode||'')}</small></span></div><div class="set-scores">${(m.sets||[]).map(s=>`<span>${s.join('–')}</span>`).join('')}</div><div class="match-foot"><span>${esc(m.date.replaceAll('-','.'))} · ${esc(m.time||'시간 미정')}${m.time?' KST':''}</span><span>경기·세트 기록 ↗</span></div></a>`;}
function render(){let t=db.teams[gender];document.querySelector('.nt-page').dataset.gender=gender;document.querySelectorAll('[data-gender]').forEach(b=>{if(b.tagName==='BUTTON')b.setAttribute('aria-pressed',String(b.dataset.gender===gender))});
const u=new URL(location.href);u.searchParams.set('gender',gender);history.replaceState(null,'',u);let past=t.matches.filter(m=>m.date<=db.snapshotDate&&m.score),future=t.matches.filter(m=>m.date>db.snapshotDate&&!m.score).sort((a,b)=>a.date.localeCompare(b.date));$('match-cards').innerHTML=matchCard(past[0])+matchCard(future[0],true);
renderCompetitions();renderProgress();
$('roster-select').innerHTML=t.rosters.map(r=>`<option value="${esc(r.id)}">${esc(r.label)}</option>`).join('');position='전체';renderRoster();
$('history-scope').textContent=t.historyAvailable?'남자대표팀 기록':'기존 기록은 남자부 기준';$('history-notice').hidden=t.historyAvailable;$('history-notice').textContent='여자대표팀의 히스토리·세대추적은 자료 구축 전입니다. 아래 링크는 현재 운영 중인 남자대표팀 기록으로 연결됩니다.';
$('team-content').hidden=false;$('load-status').textContent=t.label+' 기록을 표시합니다.';$('load-status').className='sr-only';route();}
function renderCompetitions(){
 const year=$('year-select').value,t=db.teams[gender];$('selected-year').textContent=year;
 $('competition-caption').textContent=year==='2026'?`${t.label} · 4개 대회 종료 · 최종 성적`:`${t.label} · 이전 기록`;
 if(year!=='2026'){$('competition-cards').innerHTML=`<div class="year-empty"><strong>${year}년 요약 자료 연결 준비 중</strong><p>자료 미구축은 미출전을 뜻하지 않습니다.</p><a href="${origin}national-team-history.html?scope=senior">기존 성인대표팀 히스토리 보기 ↗</a>${gender==='women'?'<small>현재 히스토리는 남자부 중심으로 제공됩니다.</small>':''}</div>`;return;}
 $('competition-cards').innerHTML=t.competitions.map(c=>{const officialResult=c.sources.find(s=>s.url.includes('entry=result'))||c.sources[0],continental=c.id.includes('continental'),games=c.id.includes('asian-games'),title=c.title.replace('남자','').replace('여자','');return `<article class="tournament-card ${games?'games':'avc'} ${continental?'is-qualifier':''}"><div class="tournament-top"><span class="family-label">${games?'ASIAN GAMES':'AVC'} · ${gender==='men'?'남자부':'여자부'}</span><span class="ended">대회 종료</span></div><div class="tournament-main"><div><h3><a href="${esc(c.kvlHref?url(c.kvlHref):officialResult.url)}" ${c.kvlHref?'':'target="_blank" rel="noopener"'}>${esc(title)}</a></h3><p>${c.start.slice(5).replace('-','.')} – ${c.end.slice(5).replace('-','.')}<span>${esc(c.location)}</span></p></div><div class="final-place"><small>최종 성적</small><strong>${c.rank===1?'우승':c.rank+'<em>위</em>'}</strong></div></div><div class="qualification-note ${continental?'gold':''}">${continental?(gender==='men'?'<b>2027 월드컵 출전권 확보</b><span>LA28 아시아 직행권 미획득</span>':'<b>LA28·월드컵 직행권 미획득</b><span>월드컵은 이후 세계랭킹 경로로 확보</span>'):'LA28·월드컵 직접 출전권 배정 대회 아님'}</div><div class="tournament-links">${c.kvlHref?`<a href="${url(c.kvlHref)}">KVL 대회 보기 <span>↗</span></a>`:'<span class="unbuilt">KVL 상세 준비 중</span>'}<a href="${esc(officialResult.url)}" target="_blank" rel="noopener">공식 결과 ↗</a></div></article>`}).join('');
}
function renderProgress(){
 const t=db.teams[gender],r=t.ranking,men=gender==='men';
 $('summary-strip').innerHTML=`<a class="summary-ranking" href="#ranking"><span>대한민국 세계랭킹</span><strong>${r.rank}<em>위</em> <small>${r.points.toFixed(2)}점</small></strong><small>2026.10.15 공식 기준</small></a><a class="summary-cup" href="#roadmap"><span>2027 FIVB 월드컵</span><strong>출전권 확보 <i>✓</i></strong><small>${men?'아시아선수권 3위':'10.2 세계랭킹 경로'}</small></a><a class="summary-la" href="#roadmap"><span>LA 2028 올림픽</span><strong>월드컵에서 다음 도전 <b>→</b></strong><small>출전권 미확보 · 로드맵 보기</small></a>`;
 const steps=[
 ['2026','아시아선수권',men?'3위 · 동메달':'최종 6위','LA28 아시아 직행권 미획득','done'],
 ['2027','FIVB 월드컵','출전권 확보',`${men?'아시아선수권 3위로 진출':'2026.10.2 세계랭킹 경로로 진출'}<br>올림픽 미확보 팀 중 상위 3팀에 LA28 출전권`,'current'],
 ['2028','세계랭킹','최종 출전 기회','VNL 예선 종료 후 랭킹으로 3자리 배정<br>대륙 대표성 우선 규정 적용','future'],
 ['LA28','로스앤젤레스 올림픽','진출 목표','월드컵 또는 세계랭킹 경로로 도전','goal']];
 $('roadmap-steps').innerHTML=steps.map(([y,title,status,note,state])=>`<li class="${state}"><span class="timeline-dot" aria-hidden="true"></span><div class="step-year">${y}</div><div class="step-body"><div><h3>${title}</h3><span class="step-status">${status}</span></div><p>${note}</p></div></li>`).join('');
 $('ranking-head').innerHTML=`<div class="ranking-korea"><span class="taegeuk" aria-hidden="true"></span><strong>대한민국 ${men?'남자':'여자'}대표팀</strong><span>아시아 ${r.confederationRank}위</span></div><div class="ranking-number"><strong>${r.rank}<em>위</em></strong><div><b>${r.points.toFixed(2)}<span> pts</span></b><small>직전 대비 · 확인 불가</small></div></div>`;
 const names={JPN:'일본',IRI:'이란',KOR:'대한민국',CHN:'중국',BRN:'바레인',THA:'태국',VIE:'베트남'};
 $('asia-rankings').innerHTML=r.asia.slice(0,5).map((x,i)=>`<tr class="${x.federationCode==='KOR'?'is-korea':''}"><td>${i+1}</td><th scope="row">${names[x.federationCode]||esc(x.federationName)}</th><td>${x.rank}위</td><td>${x.decimalPoints.toFixed(2)}</td></tr>`).join('');
 $('ranking-official').href=r.sourcePage;$('ranking-api').href=r.sourceApi;
 const sourceEntries=[...t.competitions.flatMap(c=>c.sources),...db.qualificationSources,{title:'Volleyball World · 공식 세계랭킹',url:r.sourcePage}];
 $('official-sources').innerHTML=[...new Map(sourceEntries.map(x=>[x.url,x])).values()].map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title)} ↗</a>`).join('');
}
function renderRoster(){const r=db.teams[gender].rosters.find(r=>r.id===$('roster-select').value);$('coach-name').textContent=r.coach||'미확인';$('roster-title').textContent=r.label;$('roster-status').textContent=r.players.length?r.players.length+'명 · '+r.status:r.status;$('roster-detail').href=url(r.href);$('roster-source').textContent=r.source+(r.sourceDate?' · '+r.sourceDate:'');
document.querySelector('.position-filters').hidden=!r.players.length;document.querySelector('.position-filters').innerHTML=['전체','S','OH','OP','MB','L'].map(p=>`<button type="button" data-position="${p}" aria-pressed="${p===position}">${p}${p==='전체'?' '+r.players.length:''}</button>`).join('');const rows=r.players.filter(p=>position==='전체'||p.position===position);$('players').innerHTML=rows.length?rows.map(p=>`<div class="player-row"><span class="pos">${esc(p.position)}</span><div>${p.profileId?`<a href="${origin}player.html?id=${encodeURIComponent(p.profileId)}">${esc(p.name)} <span aria-hidden="true">↗</span></a>`:`<strong>${esc(p.name)}<span class="player-number">${p.number??''}</span></strong>`}<small>${esc(p.club||'소속 미확인')}</small></div></div>`).join(''):`<div class="empty-roster">${r.players.length?'해당 포지션 선수가 없습니다.':'공식 명단 연결 준비 중입니다.'}</div>`;}
document.querySelector('.gender-switch').addEventListener('click',e=>{const b=e.target.closest('[data-gender]');if(!b||!db)return;gender=b.dataset.gender;render()});$('year-select').addEventListener('change',renderCompetitions);$('roster-select').addEventListener('change',()=>{position='전체';renderRoster()});document.querySelector('.position-filters').addEventListener('click',e=>{const b=e.target.closest('[data-position]');if(b){position=b.dataset.position;renderRoster()}});document.querySelector('.top-button').addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
fetch('snapshot.json').then(r=>{if(!r.ok)throw Error('자료 로드 오류');return r.json()}).then(data=>{db=data;render()}).catch(()=>{$('load-status').innerHTML='대표팀 자료를 불러오지 못했습니다. <button type="button" id="retry">다시 불러오기</button>';$('retry').onclick=()=>location.reload()});})();
